-- 진짜 필요한 자리

@Query(value = """
        select
            t.name           as team_name,
            m.username       as username,
            m.age            as age,
            rank() over (partition by t.team_id order by m.age desc)
                             as age_rank
        from member m
        join team t on t.team_id = m.team_id
        where m.age >= :minAge
        """, nativeQuery = true)
List<Object[]> rankByTeam(@Param("minAge") int minAge);

@Test
@Transactional
void 순위() {
    em.clear();
    for (Object[] r : memberRepository.rankByTeam(10)) {
        System.out.printf("%-8s %-6s %2s %s%n", r[0], r[1], r[2], r[3]);
    }
}

