@Query(value = """
        with recursive sub as (
            select team_id, name, parent_id, 0 as depth
            from team where parent_id is null
            union all
            select t.team_id, t.name, t.parent_id, sub.depth + 1
            from team t join sub on t.parent_id = sub.team_id
        )
        select name, depth from sub order by depth, name
        """, nativeQuery = true)
